    <circle r={29} fill="#ffd45a" stroke="#c98d10" strokeWidth={3} />
    <text y={13} textAnchor="middle" fontFamily={FONT} fontWeight={800} fontSize={38} fill="#8a5d08">$</text>
    <path d="M -24 -12 Q -10 -30 8 -26" stroke="rgba(255,255,255,0.7)" strokeWidth={5} fill="none" strokeLinecap="round" />
  </g>
);

const Billete: React.FC<{x: number; y: number; r?: number; k?: number; c?: string}> = ({x, y, r = 0, k = 1, c = '#58b068'}) => (
  <g transform={`translate(${x} ${y}) rotate(${r}) scale(${k})`}>
    <rect x={-86} y={-44} width={180} height={100} rx={8} fill="rgba(0,0,0,0.25)" />
    <rect x={-90} y={-50} width={180} height={100} rx={8} fill={c} stroke="rgba(0,0,0,0.4)" strokeWidth={4} />
    <rect x={-76} y={-38} width={152} height={76} rx={4} fill="none" stroke="rgba(255,255,255,0.5)" strokeWidth={3} />
    <circle r={26} fill="rgba(255,255,255,0.3)" />
    <text y={14} textAnchor="middle" fontFamily={FONT} fontWeight={800} fontSize={40} fill="rgba(0,0,0,0.5)">$</text>
    <path d="M -70 -30 Q -40 -44 -10 -38" stroke="rgba(255,255,255,0.6)" strokeWidth={5} fill="none" strokeLinecap="round" />
  </g>
);

// LED rojo con halo y punto blanco
const Led: React.FC<{x: number; y: number; r?: number; a?: number; c?: string; ph?: number}> = ({x, y, r = 14, a = 1, c = RED, ph = 0}) => {
  const {s} = useS();
  const p = 0.78 + 0.22 * Math.sin(s * 3.2 + ph);
  if (a <= 0.01) return null;
  return (
    <g opacity={a}>
      <circle cx={x} cy={y} r={r * 5.5 * p} fill={c} opacity={0.1} />
      <circle cx={x} cy={y} r={r * 3 * p} fill={c} opacity={0.22} />
      <circle cx={x} cy={y} r={r * 1.7} fill={c} opacity={0.5} />
      <circle cx={x} cy={y} r={r} fill="#ff8a8a" stroke={c} strokeWidth={2} />
      <circle cx={x - r * 0.3} cy={y - r * 0.3} r={r * 0.35} fill="#fff" opacity={0.9} />
    </g>
  );
};

// cartera de cuero; abre 0..1 (la solapa baja), lleno 0..1 (billetes que asoman)
