const SON = en('son'), CATORCE = en('catorce'), MES = en('mes'), FACTURA = en('factura'), PAGAS = en('pagas'), NADA = en('nada');
const Y6 = en('y', 4), TODO = en('todo'), PAIS = en('pais'), DIECI = en('diecinueve'), MILLONES = en('millones'), NADIE = en('nadie');
