// ================= SITIO A: el televisor apagado y su lucecita (E1) =================
const OTROS: [number, number, number][] = [[110, 330, 9], [930, 270, 11], [300, 170, 8], [640, 140, 10], [170, 1690, 9], [760, 1850, 8], [1010, 1330, 10], [50, 900, 9], [980, 420, 7]];
const SA_CAM = [P(0, 540, 1390, 1.7), P(COBRANDO, 560, 1400, 2.2), P(UNICO - 0.35, 560, 1300, 1.6), P(UNICO + 0.55, 540, 1000, 1.0), P(ESA, 540, 1000, 1.0)];
