const SitioA: React.FC<{led?: number; fin?: boolean}> = ({led = 1, fin = false}) => {
  const {s} = useS();
  return (
    <AbsoluteFill>
      <Camara paradas={fin ? SG_CAM : SA_CAM}>
        <Textura tipo="fibra" base={SALA_BASE} linea="rgba(110,150,255,0.18)" luz="rgba(110,150,255,0.10)" semilla={91} />
        <svg width={1080} height={1920} style={{position: 'absolute', inset: 0}}>
          <Tele led={led} />
          {/* la moneda que sale por el cable */}
          {!fin && <Recorrido puntos={[[760, 1500], [760, 1600], [790, 1680], [880, 1700]]} t0={COBRANDO - 0.05} t1={COBRANDO + 1.1} color="rgba(255,200,61,0.7)" render={(x, y) => <Moneda x={x} y={y} k={0.5 + 0.1 * Math.sin(s * 10)} r={s * 300} />} />}
          {!fin && OTROS.map(([x, y, r], i) => <Led key={i} x={x} y={y} r={r} a={eo(ro(s, UNICO + i * 0.19, UNICO + i * 0.19 + 0.3))} ph={i} />)}
        </svg>
        <Brillo x={540} y={1390} r={340} color={fin ? 'rgba(110,150,255,0.25)' : 'rgba(255,60,60,0.45)'} />
        {!fin && <Ondas x={540} y={1390} t0={COBRANDO} color={RED} radio={300} />}
        {!fin && <Ondas x={540} y={1000} t0={UNICO} color={RED} radio={520} />}
        <Polvo n={18} color="rgba(160,190,255,0.5)" />
      </Camara>
    </AbsoluteFill>
  );
};

