// ================= SITIO B: por dentro del cable de cobre (E3) =================
const CAB: [number, number][] = [[540, 1260], [575, 1060], [510, 880], [540, 720]];
const CABD: [number, number][] = [[540, 1990], ...CAB, [540, -60]];
const SB_CAM = [...seguir(CAB, CUANTO, SUMAN - 0.3, 1.45, 6), P(SUMAN + 0.7, 540, 900, 1.2)];
const SitioB: React.FC = () => {
  const {s, spr} = useS();
  const ball = spr(SUMAN, 9, 120);
  const pts = (dx: number) => CABD.map((p) => `${p[0] + dx},${p[1]}`).join(' ');
  return (
    <AbsoluteFill>
      <Camara paradas={SB_CAM}>
        <Textura tipo="fibra" base="radial-gradient(circle at 50% 45%, #7a3d12 0%, #3a1a08 70%, #170a03 100%)" linea="rgba(255,170,90,0.3)" luz="rgba(255,190,120,0.18)" semilla={93} />
        <svg width={1080} height={1920} style={{position: 'absolute', inset: 0}}>
          <polyline points={pts(0)} fill="none" stroke="rgba(20,8,2,0.85)" strokeWidth={360} strokeLinejoin="round" strokeLinecap="round" />
          {[-4, -3, -2, -1, 0, 1, 2, 3, 4].map((k) => (
            <g key={k}>
              <polyline points={pts(k * 36)} fill="none" stroke={k % 2 ? '#b8651f' : '#d98a3c'} strokeWidth={30} strokeLinejoin="round" strokeLinecap="round" />
              <polyline points={pts(k * 36 - 7)} fill="none" stroke="rgba(255,225,170,0.5)" strokeWidth={6} strokeLinejoin="round" strokeLinecap="round" />
            </g>
          ))}
